// MikroTik RouterOS (SSH) – estado do sistema, interfaces e o papel btest
// no teste de enlace (ADR 015).
//
// O teste de enlace usa o Bandwidth Test nativo do RouterOS: o
// `bandwidth-server` serve (porta 2000/TCP, fixa no RouterOS) e o
// `/tool bandwidth-test` dirige. Nada é instalado. O `tp_serve` anota no
// `handle` o estado anterior do servidor e o usuário temporário que criou; o
// `tp_stop` desfaz exatamente isso, e só isso.

// ---------------------------------------------------------------- utilitários

fn or_default(value, fallback) {
    if value == () { fallback } else { value }
}

// Ação de papel chamada sem os parâmetros do teste (pela aba, à mão): recusa
// antes de mexer em qualquer coisa.
fn require_link_test(params, key) {
    if params[key] == () {
        throw "Esta ação faz parte do teste de enlace e recebe os parâmetros dele: rode o teste pela topologia.";
    }
}

// Mensagem de um erro pego por `catch` (texto do `throw` ou erro do sistema).
fn error_text(err) {
    if type_of(err) == "map" && err.message != () { err.message } else { err.to_string() }
}

// "1w2d3h4m5s" ou "2d 03:04:05" → segundos.
fn ros_seconds(text) {
    if text == () { return (); }
    let value = trimmed(text);
    let weights = [604800, 86400, 3600, 60, 1];
    let g = regex_groups(value, "^(?:([0-9]+)w)?(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?$");
    if g == () {
        g = regex_groups(value, "^(?:([0-9]+)w)?(?:([0-9]+)d)?\\s*([0-9]+):([0-9]+):([0-9]+)$");
    }
    if g == () { return (); }
    let total = 0;
    for i in 0..5 {
        if g[i] != () { total += parse_int(g[i]) * weights[i]; }
    }
    total
}

// "857.6MiB" → bytes.
fn ros_bytes(text) {
    if text == () { return (); }
    let g = regex_groups(text, "([0-9.]+)\\s*([KMGT]?)i?B");
    if g == () { return (); }
    let factor = if g[1] == "K" { 1024.0 } else if g[1] == "M" { 1048576.0 } else if g[1] == "G" { 1073741824.0 } else if g[1] == "T" { 1099511627776.0 } else { 1.0 };
    (parse_float(g[0]) * factor).round().to_int()
}

fn ros_percent(text) {
    if text == () { return (); }
    let digits = regex_capture(text, "([0-9]+)");
    if digits == () { () } else { parse_int(digits) }
}

// "94.5Mbps" (valor e unidade separados) → bits por segundo.
fn rate_bps(value, unit) {
    let n = parse_float(value);
    let u = unit.to_lower();
    if u.starts_with("t") { n * 1000000000000.0 }
    else if u.starts_with("g") { n * 1000000000.0 }
    else if u.starts_with("m") { n * 1000000.0 }
    else if u.starts_with("k") { n * 1000.0 }
    else { n }
}

// Teto de banda em kbit/s (inteiro), ou `()` sem limite.
fn limit_kbps(limit) {
    if limit == () { return (); }
    let mbps = if type_of(limit) == "f64" { limit } else { limit.to_float() };
    let kbps = (mbps * 1000.0).round().to_int();
    if kbps > 0 { kbps } else { () }
}

fn yes_no(value) {
    if value == "yes" || value == "true" { "yes" } else { "no" }
}

// --------------------------------------------------------------- leitura

fn resource(device) {
    parse_kv(device.run("/system resource print"), ":")
}

fn detect(device, params) {
    let res = resource(device);
    let board = parse_kv(device.run("/system routerboard print"), ":");
    let version = res.version;
    let model = board.model;
    if model == () { model = res["board-name"]; }
    #{
        firmware: if version == () { () } else { regex_capture(version, "^([0-9][0-9A-Za-z.]*)") },
        channel: if version == () { () } else { regex_capture(version, "\\(([a-z -]+)\\)") },
        model: model,
        board: res["board-name"],
        architecture: res["architecture-name"],
        routerboard: board.routerboard == "yes"
    }
}

fn system_status(device, params) {
    let res = resource(device);
    #{
        version: res.version,
        board: res["board-name"],
        uptime: ros_seconds(res.uptime),
        cpu_load: ros_percent(res["cpu-load"]),
        cpu_count: res["cpu-count"],
        free_memory: ros_bytes(res["free-memory"]),
        total_memory: ros_bytes(res["total-memory"])
    }
}

fn interfaces(device, params) {
    let out = device.run(":foreach i in=[/interface find] do={:put ([/interface get $i type] . \";\" . [/interface get $i running] . \";\" . [/interface get $i disabled] . \";\" . [/interface get $i rx-byte] . \";\" . [/interface get $i tx-byte] . \";\" . [/interface get $i name])}");
    let rows = [];
    for line in lines(out) {
        let cols = line.split(";");
        if cols.len() < 6 { continue; }
        let name = cols[5];
        for i in 6..cols.len() { name += ";" + cols[i]; }
        let state = if cols[2] == "true" { "disabled" } else if cols[1] == "true" { "up" } else { "down" };
        rows.push(#{
            name: name,
            "type": cols[0],
            state: state,
            rx_bytes: parse_int(cols[3]),
            tx_bytes: parse_int(cols[4])
        });
    }
    rows
}

// --------------------------------------------------- teste de enlace (btest)

// Só usuário com este prefixo é criado e removido pelo teste.
fn test_user(user) {
    if user == () || !regex_match(user, "^nm-test-[A-Za-z0-9_-]+$") {
        throw "Usuário de teste inválido: o teste de enlace só cria e remove usuários nm-test-….";
    }
    user
}

fn server_state(device) {
    let s = parse_kv(device.run("/tool bandwidth-server print"), ":");
    // `allowed-addresses4` só existe no RouterOS 7; () = propriedade ausente.
    let allowed = if "allowed-addresses4" in s { trimmed(s["allowed-addresses4"]) } else { () };
    #{ enabled: yes_no(s.enabled), authenticate: yes_no(s.authenticate), allowed4: allowed }
}

// IPv4 literal (a.b.c.d) — só ele vira restrição de endereço.
fn is_ipv4(text) {
    text != () && regex_capture(text, "^((?:[0-9]{1,3}\\.){3}[0-9]{1,3})$") != ()
}

// Leva o servidor a `enabled`/`authenticate`, mexendo só no que difere.
fn set_server(device, current, enabled, authenticate) {
    let args = "";
    if current.enabled != enabled { args += " enabled=" + enabled; }
    if current.authenticate != authenticate { args += " authenticate=" + authenticate; }
    if args != "" { device.run("/tool bandwidth-server set" + args); }
}

fn user_exists(device, user) {
    trimmed(device.run(":put [:len [/user find name=\"" + user + "\"]]")) != "0"
}

fn remove_user(device, user) {
    if user_exists(device, user) {
        device.run("/user remove [find name=\"" + user + "\"]");
    }
}

fn tp_serve(device, params) {
    require_link_test(params, "engine");
    if params.engine != "btest" {
        throw "O RouterOS só serve o btest (Bandwidth Test); iperf3 não roda nele.";
    }
    let before = server_state(device);
    let user = "";
    if params.requireAuth == true {
        user = test_user(params.user);
        if params.password == () || params.password == "" {
            throw "O teste com autenticação precisa da senha do usuário de teste.";
        }
        remove_user(device, user);
        device.run("/user add name=\"" + user + "\" group=read password=\"" + params.password + "\" comment=\"NetMonitor: teste de enlace\"");
        let failure = ();
        try {
            set_server(device, before, "yes", before.authenticate);
        } catch (err) {
            failure = error_text(err);
        }
        if failure != () {
            remove_user(device, user);
            throw failure;
        }
    } else {
        set_server(device, before, "yes", "no");
    }
    // Sem autenticação o servidor atenderia qualquer um durante a janela:
    // no RouterOS 7 ele fica restrito ao IP de quem vai medir.
    let restricted = false;
    if params.requireAuth != true && before.allowed4 != () && is_ipv4(params.peer) {
        device.run("/tool bandwidth-server set allowed-addresses4=" + params.peer + "/32");
        restricted = true;
    }
    let handle = #{
        engine: "btest",
        prevEnabled: before.enabled,
        prevAuthenticate: before.authenticate,
        user: user
    };
    if restricted { handle.prevAllowed4 = before.allowed4; }
    #{ port: 2000, handle: json_encode(handle) }
}

fn parse_handle(text) {
    let handle = ();
    try {
        handle = json_parse(text);
    } catch (err) {
        handle = ();
    }
    if type_of(handle) != "map" {
        throw "O `handle` do teste de enlace não é o que o tp_serve devolveu.";
    }
    handle
}

fn tp_stop(device, params) {
    require_link_test(params, "handle");
    let handle = parse_handle(params.handle);
    let enabled = handle.prevEnabled;
    let authenticate = handle.prevAuthenticate;
    if (enabled != "yes" && enabled != "no") || (authenticate != "yes" && authenticate != "no") {
        throw "O `handle` não traz o estado anterior do bandwidth-server (prevEnabled/prevAuthenticate).";
    }
    if handle.user != () && handle.user != "" {
        remove_user(device, test_user(handle.user));
    }
    if handle.prevAllowed4 != () {
        let previous = handle.prevAllowed4;
        if previous != "" && regex_capture(previous, "^([0-9./,]+)$") == () {
            throw "O `handle` traz um allowed-addresses4 que não é lista de endereços.";
        }
        device.run("/tool bandwidth-server set allowed-addresses4=\"" + previous + "\"");
    }
    set_server(device, server_state(device), enabled, authenticate);
    #{ stopped: true }
}

// Lê a saída do `/tool bandwidth-test`: o último `*-total-average` de cada
// sentido é o resultado; o último `status` explica a falha.
fn parse_bandwidth_test(text, direction) {
    let t = text;
    t.replace("\r", "\n");
    let status = "";
    let tx = ();
    let rx = ();
    for line in lines(t) {
        let s = regex_capture(line, "^status:\\s*(.+)$");
        if s != () { status = trimmed(s); }
        let g = regex_groups(line, "^(tx|rx)-total-average:\\s*([0-9.]+)\\s*([A-Za-z]*)");
        if g != () {
            if g[0] == "tx" { tx = rate_bps(g[1], g[2]); } else { rx = rate_bps(g[1], g[2]); }
        }
    }
    if status.contains("authentication") {
        throw "O servidor btest recusou o usuário e a senha do teste (" + status + ").";
    }
    if tx == () && rx == () {
        let reason = if status == "" { trimmed(text) } else { status };
        throw "O teste não trouxe resultado: " + reason;
    }
    // O RouterOS imprime as médias (zeradas) mesmo quando nem conecta: o que
    // vale é o status final — "done testing" (ou "running" no último quadro).
    if status != "" && !status.contains("done") && !status.contains("running") {
        throw "O teste não trouxe resultado: " + status;
    }
    #{
        engine: "btest",
        txBps: if direction == "receive" { () } else { or_default(tx, 0.0) },
        rxBps: if direction == "send" { () } else { or_default(rx, 0.0) },
        txBytes: 0,
        rxBytes: 0,
        retransmits: (),
        samples: []
    }
}

fn tp_run(device, params) {
    require_link_test(params, "target");
    if or_default(params.engine, "btest") != "btest" {
        throw "O RouterOS só dirige o btest (Bandwidth Test).";
    }
    if params.port != () && params.port != 2000 {
        throw "O RouterOS só testa contra a porta 2000 do servidor btest.";
    }
    let direction = or_default(params.direction, "both");
    let duration = or_default(params.durationS, 5);
    let ros_direction = if direction == "send" { "transmit" } else if direction == "receive" { "receive" } else { "both" };
    let command = "/tool bandwidth-test address=" + params.target + " protocol=tcp direction=" + ros_direction + " duration=" + duration + "s connection-count=1";
    let limit = limit_kbps(params.limitMbps);
    if limit != () {
        if direction != "receive" { command += " local-tx-speed=" + limit + "k"; }
        if direction != "send" { command += " remote-tx-speed=" + limit + "k"; }
    }
    if params.user != () && params.user != "" {
        command += " user=" + params.user;
        if params.password != () { command += " password=\"" + params.password + "\""; }
    }
    let r = device.ssh_live(command, #{
        timeout_ms: duration * 1000 + 20000,
        progress: #{ pattern: "(?<flow>tx|rx)-current:\\s*(?<value>[0-9.]+)\\s*(?<unit>[A-Za-z]*bps)" }
    });
    parse_bandwidth_test(r.stdout + "\n" + r.stderr, direction)
}
